const $=id=>document.getElementById(id);let page=0,observations={};
window.probePath=function(path,context=window){try{let value=context;for(const key of path.split('.')){if(key==='window'&&value===context)continue;if(value==null||!(key in Object(value)))return'absent';value=value[key]}return value==null?'absent':'present'}catch{return'unknown'}};
window.runFeatureAudit=function(){const results=omniAudit.entries.map(e=>({id:e.id,feature:e.name,result:probePath(e.featurePath)}));window.omniFeatureAuditResult={schemaVersion:1,sourceCommit:omniAudit.commit,environment:'current-browser-not-console-certified',secureContext:isSecureContext,results};observations=Object.fromEntries(results.map(x=>[x.id,x.result]));render();return omniFeatureAuditResult};
function render(){$('rows').replaceChildren();for(const e of omniAudit.entries.slice(page*4,page*4+4)){const tr=document.createElement('tr');for(const text of[e.name,e.sourceStatus.replaceAll('-',' '),observations[e.id]||'Not checked']){const td=document.createElement('td');td.textContent=text;tr.append(td)}$('rows').append(tr)}$('page').textContent=(page+1)+' of '+Math.ceil(omniAudit.entries.length/4);$('prev').disabled=page===0;$('next').disabled=(page+1)*4>=omniAudit.entries.length;if(Object.keys(observations).length)$('summary').textContent='Presence checked; functionality still needs testing.'}
$('probe').onclick=runFeatureAudit;$('prev').onclick=()=>{page--;render();$('next').focus()};$('next').onclick=()=>{page++;render();$('prev').focus()};let ps=true;$('glyphs').onclick=()=>{ps=!ps;$('glyphs').textContent=ps?'PlayStation hints':'Xbox hints';$('hints').textContent=ps?'D-pad · Move / Cross · Select / Circle · Back':'D-pad · Move / A · Select / B · Back'};window.omniPadController=window.omniMediaController=function(a){const nodes=[...document.querySelectorAll('button')].filter(e=>!e.disabled);const i=nodes.indexOf(document.activeElement);if(['up','down','left','right'].includes(a)){nodes[(i+(a==='up'||a==='left'?-1:1)+nodes.length)%nodes.length]?.focus();return true}if(a==='confirm'){document.activeElement?.click();return true}return false};document.addEventListener('keydown',e=>{const a={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key];if(a&&omniPadController(a))e.preventDefault()});render();
